[{"order":1,"type":"heading","text":"Server State and Caching in React Native: React Query vs Apollo Client"},{"order":2,"type":"paragraph","text":"Managing server state in mobile applications differs significantly from web applications due to unstable network conditions, backgrounding behavior, and memory constraints. This tutorial explores two leading libraries for React Native: TanStack Query (React Query) for REST/GraphQL endpoints, and Apollo Client specifically for GraphQL."},{"order":3,"type":"subheading","text":"1. Setting Up TanStack Query in React Native"},{"order":4,"type":"paragraph","text":"TanStack Query requires explicit handling of React Native\'s app state (active, background, inactive) to properly refetch data when the user returns to the application. First, install the necessary packages."},{"order":5,"type":"code","text":"npm install @tanstack/react-query
npm install @react-native-community/netinfo"},{"order":6,"type":"paragraph","text":"Next, configure the QueryClient and integrate it with React Native\'s AppState API for optimal cache revalidation."},{"order":7,"type":"code","text":"import React, { useEffect } from 'react';
import { AppState, Platform } from 'react-native';
import { QueryClient, QueryClientProvider, focusManager } from '@tanstack/react-query';
import type { AppStateStatus } from 'react-native';

function onAppStateChange(status: AppStateStatus) {
  if (Platform.OS !== 'web') {
    focusManager.setFocused(status === 'active');
  }
}

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 2,
      staleTime: 1000 * 60 * 5,
    },
  },
});

export default function App() {
  useEffect(() => {
    const subscription = AppState.addEventListener('change', onAppStateChange);
    return () => subscription.remove();
  }, []);

  return (
    <QueryClientProvider client={queryClient}>
      {/* Your Navigator or Root Component */}
    </QueryClientProvider>
  );
}"},{"order":8,"type":"subheading","text":"2. Fetching and Caching Data with React Query"},{"order":9,"type":"paragraph","text":"Using the useQuery hook allows components to consume cached data instantly while fetching updates in the background. Network awareness ensures requests are deferred when offline."},{"order":10,"type":"code","text":"import React from 'react';
import { View, Text, FlatList, ActivityIndicator, StyleSheet } from 'react-native';
import { useQuery } from '@tanstack/react-query';

interface User {
  id: number;
  name: string;
}

async function fetchUsers(): Promise<User[]> {
  const response = await fetch('https://jsonplaceholder.typicode.com/users');
  if (!response.ok) throw new Error('Network response was not ok');
  return response.json();
}

export function UserList() {
  const { data, isLoading, error, refetch, isRefetching } = useQuery({
    queryKey: ['users'],
    queryFn: fetchUsers,
  });

  if (isLoading) return <ActivityIndicator size="large" style={styles.centered} />;
  if (error) return <Text style={styles.centered}>Error: {error.message}</Text>;

  return (
    <FlatList
      data={data}
      keyExtractor={(item) => item.id.toString()}
      renderItem={({ item }) => (
        <View style={styles.item}>
          <Text>{item.name}</Text>
        </View>
      )}
      onRefresh={refetch}
      refreshing={isRefetching}
    />
  );
}

const styles = StyleSheet.create({
  centered: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  item: { padding: 16, borderBottomWidth: 1, borderBottomColor: '#ccc' },
});"},{"order":11,"type":"subheading","text":"3. Setting Up Apollo Client in React Native"},{"order":12,"type":"paragraph","text":"If your React Native application relies on GraphQL, Apollo Client provides a normalized in-memory cache which automatically updates related queries when mutations occur."},{"order":13,"type":"code","text":"npm install @apollo/client graphql"},{"order":14,"type":"paragraph","text":"Configure the ApolloClient instance with a standard InMemoryCache and wrap your root component."},{"order":15,"type":"code","text":"import React from 'react';
import { ApolloClient, InMemoryCache, ApolloProvider } from '@apollo/client';

const client = new ApolloClient({
  uri: 'https://api.spacex.land/graphql/',
  cache: new InMemoryCache(),
});

export default function App() {
  return (
    <ApolloProvider client={client}>
      {/* Your Root Component */}
    </ApolloProvider>
  );
}"},{"order":16,"type":"subheading","text":"4. Querying and Normalizing Data with Apollo Client"},{"order":17,"type":"paragraph","text":"Apollo Client uses the useQuery hook to execute GraphQL queries and automatically normalizes the returned entities based on their __typename and id fields."},{"order":18,"type":"code","text":"import React from 'react';
import { View, Text, FlatList, ActivityIndicator } from 'react-native';
import { useQuery, gql } from '@apollo/client';

const GET_LAUNCHES = gql`
  query GetLaunches {
    launchesPast(limit: 10) {
      id
      mission_name
      launch_date_utc
    }
  }
`;

export function LaunchList() {
  const { loading, error, data } = useQuery(GET_LAUNCHES);

  if (loading) return <ActivityIndicator size="large" />;
  if (error) return <Text>Error: {error.message}</Text>;

  return (
    <FlatList
      data={data.launchesPast}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => (
        <View style={{ padding: 16 }}>
          <Text style={{ fontWeight: 'bold' }}>{item.mission_name}</Text>
          <Text>{item.launch_date_utc}</Text>
        </View>
      )}
    />
  );
}"},{"order":19,"type":"subheading","text":"Best Practices for Mobile Caching"},{"order":20,"type":"bullet_point","text":"Persistence: Use AsyncStorage or MMKV to persist the React Query or Apollo cache across app restarts to enable offline support."},{"order":21,"type":"bullet_point","text":"Garbage Collection: Configure gcTime (React Query) or cache policies carefully to prevent memory bloat on low-RAM mobile devices."},{"order":22,"type":"bullet_point","text":"Optimistic Updates: Implement optimistic updates for mutations to ensure high perceived performance and instantaneous UI feedback."}]
